    for (var i=0;i<STEPS;i++){
      var p = qs('[data-pane="'+i+'"]');
      p.classList.toggle("active", i===current);
    }
    document.querySelector(".prog-bar").style.width = ((current+1)/STEPS*100)+"%";
    document.getElementById("prev").disabled = (current===0);
    document.getElementById("next").hidden = (current===STEPS-1);
    document.getElementById("finish").hidden = (current!==STEPS-1);
  }

  function step(dir){
    current += dir;
    if (current<0) current=0;
    if (current>STEPS-1) current=STEPS-1;
    renderState();
  }

  function openModal(){
    document.body.classList.add("no-scroll");
    document.documentElement.style.overflow="hidden";
    document.body.style.overflow="hidden";
