  }

  function makeSortable(list){
    var dragging = null;
    function itemAt(x,y){
      var e = document.elementFromPoint(x,y);
      if (!e) return null;
      return e.closest(".sc-item");
    }
    list.addEventListener("touchstart", function(){ }, { passive: true });
    // touch drag
    list.addEventListener("touchmove", function(e){
      if (!dragging) return;
      ev.preventDefault();
      var t = e.touches[0];
      var target = itemAt(t.clientX, t.clientY);
      if (target && target!==dragging && list.contains(target)){
        list.insertBefore(dragging, target);
      }
    }, {passive:false});
    document.addEventListener("touchend", function(){ dragging=null; }, { once=true });
    // HTML5 for desktop
    list.querySelectorAll(".sc-item").forEach(function(li){
      li.addEventListener("dragstart", function(){ dragging = this; })
      li.addEventListener("dragend", function(){ dragging=null; })
    });
    list.addEventListener("dragover", function(e){
      e.preventDefault();
      if (!dragging) return;
      var target = itemAt(e.clientX, e.clientY);
      if (target && target!==dragging){
        list.insertBefore(dragging, target);
      }
    });
    list.addEventListener("drop", function(e){ e.preventDefault(); dragging=null; });
  }

