    for (var i=0;i<items.length;i++){
      var li = items[i];
      var type, pos, delta;
      type = li.getAttribute("data-type");
      pos = Array.prototype.indexOf.call(li.parentNode.children, li);
      if (pos===0) delta=1; else if (pos===3) delta=-1; else continue;
      counts[type] = (counts[type]||0) + delta;
    }
    return counts;
  }

  function showResult(){
    if (document.getElementById("res").classList.contains("open")) return;
