    if (bars.dataset.done==="1") return;
    // (re-render each time for animation)
    bars.dataset.done="1";
    showBars();
  }

  function showBars(){
    var counts = collectScores();
    var s = ["d","i","s","c"].map(function(t){ return Math.max(-24, Math.min(24, counts[t])); });
    var labels = { d:"Доминирование", i:"Влияние", s:"Стабильность", c:"Соответствие" };
    var bars = qs("#resBars");
    bars.innerHTML = "";
    s.forEach(function(v, idx){
      var label = ["d","i","s","c"][idx];
      var row = el("div");
      row.className = "bar-row";
      var top = el("div");
      top.className = "top";
      var span = el("span"); span.className="lbl";
      span.innerHTML = "<b class='"+label+"'>"+label.toUpperCase()+"</b> "+labels[label];
      var val = el("span"); val.textContent = (v>=0?"+":"")+v;
      top.appendChild(span); top.appendChild(val);
      row.appendChild(top);
      var track = el("div");
      track.className="bar-track";
      var total = v>=0?24 +(-24): -24 +24; // [-24,24]; zero at center
      // center zero at 50%; left negative, right positive
      // fill from center
      var fill = el("div"); fill.className="bar-fill "+label;
      var mid = 50; // zero point
      if (v>=0){ fill.style.left = mid+"%"; fill.style.width = ((v)/48*100)+"%"; }
      else { fill.style.width = ((-v)/48*100)+"%"; fill.style.left = (mid - ((-v)/48*100))+"%"; }
      track.appendChild(fill);
      row.appendChild(track);
      bars.appendChild(row);
    });
  }

  renderAll();
});
'''

